import {
  CONFUSABLES,
  PROFANITY_EXACT,
  PROFANITY_PREFIX,
  PROFANITY_SUBSTRING,
  RESERVED_EXACT,
  RESERVED_SUBSTRING,
} from './name-blocklist';

export type ModerationReason =
  | 'empty'
  | 'too-short'
  | 'too-long'
  | 'charset'
  | 'pii'
  | 'reserved'
  | 'inappropriate';

export interface NameValidation {
  ok: boolean;
  reason: ModerationReason | null;
  /** Normalised name (NFKC, invisible characters stripped, spaces collapsed). */
  clean: string;
  /** A safe auto-generated alternative, e.g. "Curious Otter 42". */
  suggestion: string;
}

export const NAME_MIN_LENGTH = 2;
export const NAME_MAX_LENGTH = 20;

/** Child-safe messages. They never echo the offending word. */
export const MODERATION_MESSAGES: Record<ModerationReason, string> = {
  empty: 'Please choose a display name.',
  'too-short': `Names need at least ${NAME_MIN_LENGTH} characters.`,
  'too-long': `Names can be at most ${NAME_MAX_LENGTH} characters.`,
  charset:
    'Use letters, numbers, spaces, dashes, dots or underscores only (no emoji or symbols).',
  pii: 'Please do not use an email, phone number, website or @handle as a name.',
  reserved: 'That name is reserved. Please pick another one.',
  inappropriate: 'That name is not allowed. Please pick a kind, friendly one.',
};

// Zero-width, bidi controls, soft hyphen, BOM, word joiner, C0/C1 controls.
const INVISIBLE =
  /[­͏؜ᅟᅠ឴឵᠋-᠎​-‏‪-‮⁠-⁯ㅤ︀-️﻿ﾠ\u0000-\u001F\u007F-\u009F]/g;

// Letters + combining marks (Devanagari/Tamil/Telugu vowel signs), digits, and
// the allowed punctuation (space - _ .).
const ALLOWED = /^[\p{L}\p{M}\p{N} _.-]+$/u;

const LEET: Record<string, string> = {
  '0': 'o',
  '1': 'i',
  '3': 'e',
  '4': 'a',
  '5': 's',
  '7': 't',
  '8': 'b',
  $: 's',
  '!': 'i',
  '|': 'i',
};

function normalise(word: string): string {
  return word.normalize('NFKC').toLowerCase();
}

// Lists are normalised once so native-script entries compare equal.
const SUB = PROFANITY_SUBSTRING.map(normalise);
const PRE = PROFANITY_PREFIX.map(normalise);
const EXA = PROFANITY_EXACT.map(normalise);
const RES_SUB = RESERVED_SUBSTRING.map(normalise);
const RES_EXA = RESERVED_EXACT.map(normalise);

const hasRepeat = (w: string): boolean => /(.)\1/u.test(w);
/** Cap runs of the same character at `n` ("fuuuck" -> "fuuck" for n=2). */
const capRuns = (s: string, n: number): string =>
  s.replace(/(.)\1+/gu, (m, c: string) => c.repeat(Math.min(m.length / c.length, n)));

function fold(s: string, leet: boolean): string {
  let out = '';
  for (const ch of s.normalize('NFKC').toLowerCase()) {
    const c = CONFUSABLES[ch] ?? ch;
    out += leet ? (LEET[c] ?? c) : c;
  }
  return out;
}

/** "c u n t" / "f.u.c.k": runs of 3+ single letters become one token. */
function joinSpelledOut(tokens: string[]): string[] {
  const out: string[] = [];
  let run = '';
  const flush = () => {
    if ([...run].length >= 3) out.push(run);
    else for (const ch of run) out.push(ch);
    run = '';
  };
  for (const t of tokens) {
    if ([...t].length === 1) run += t;
    else {
      flush();
      out.push(t);
    }
  }
  flush();
  return out;
}

interface View {
  tokens: string[];
  squashed: string;
}

/** Builds the match views: leet folded / digits as separators, runs capped at 2 and 1. */
function buildViews(clean: string): View[] {
  const views: View[] = [];
  for (const leet of [true, false]) {
    const folded = fold(clean, leet);
    for (const cap of [2, 1]) {
      const c = capRuns(folded, cap);
      const tokens = joinSpelledOut(c.split(/[^\p{L}\p{M}]+/u).filter(Boolean));
      views.push({ tokens, squashed: tokens.join('') });
    }
  }
  return views;
}

function matchesList(
  views: View[],
  sub: readonly string[],
  pre: readonly string[],
  exa: readonly string[]
): boolean {
  for (let i = 0; i < views.length; i++) {
    // views alternate cap=2, cap=1; a run-collapsed view may only match words
    // that have no doubled letters themselves (so "ass" never becomes "as").
    const collapsed = i % 2 === 1;
    const ok = (w: string) => !collapsed || !hasRepeat(w);
    const { tokens, squashed } = views[i];
    for (const w of sub) if (ok(w) && squashed.includes(w)) return true;
    for (const t of tokens) {
      for (const w of pre) if (ok(w) && t.startsWith(w)) return true;
      for (const w of exa) {
        if (!ok(w)) continue;
        if (t === w || t === w + 's') return true;
      }
    }
  }
  return false;
}

function looksLikePii(clean: string): boolean {
  if (/[@＠]/.test(clean)) return true;
  if (/(https?:|www\b|\.(com|net|org|in|io|co|me|app|xyz|info|edu)\b)/i.test(clean)) {
    return true;
  }
  const digits = clean.replace(/\D/g, '');
  if (digits.length >= 6) return true;
  if (/\d{5,}/.test(clean.replace(/[ _.-]/g, ''))) return true;
  // dd/mm/yyyy-like birth dates are caught by the digit rules above.
  return false;
}

const ADJECTIVES = [
  'Curious', 'Clever', 'Bright', 'Brave', 'Happy', 'Swift', 'Calm', 'Sunny',
  'Lucky', 'Witty', 'Gentle', 'Mighty', 'Jolly', 'Cosmic', 'Zesty', 'Nimble',
];
const ANIMALS = [
  'Otter', 'Panda', 'Falcon', 'Tiger', 'Dolphin', 'Koala', 'Fox', 'Owl',
  'Rabbit', 'Peacock', 'Turtle', 'Lynx', 'Heron', 'Gecko', 'Parrot', 'Yak',
];

/** FNV-1a, used to make a fallback name stable per seed. */
function hashSeed(seed: string): number {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/** Safe-by-construction fallback ("Curious Otter 42"). Deterministic per seed. */
export function suggestSafeName(seed?: string): string {
  const h = hashSeed(seed ?? String(Math.random()));
  const a = ADJECTIVES[h % ADJECTIVES.length];
  const b = ANIMALS[Math.floor(h / 16) % ANIMALS.length];
  const n = 10 + (Math.floor(h / 256) % 90);
  return `${a} ${b} ${n}`;
}

/** Normalises a candidate name: NFKC, strips invisible/bidi characters, collapses spaces. */
export function cleanDisplayName(name: string): string {
  return name
    .normalize('NFKC')
    .replace(INVISIBLE, '')
    .replace(/\s+/gu, ' ')
    .trim();
}

export function validateDisplayName(name: unknown): NameValidation {
  const raw = typeof name === 'string' ? name : '';
  const clean = cleanDisplayName(raw);
  const suggestion = suggestSafeName(clean || undefined);
  const fail = (reason: ModerationReason): NameValidation => ({
    ok: false,
    reason,
    clean,
    suggestion,
  });

  if (clean.length === 0) return fail('empty');
  const len = [...clean].length;
  if (len < NAME_MIN_LENGTH) return fail('too-short');
  if (len > NAME_MAX_LENGTH) return fail('too-long');
  if (looksLikePii(clean)) return fail('pii');
  if (!ALLOWED.test(clean)) return fail('charset');

  const views = buildViews(clean);
  if (matchesList(views, RES_SUB, [], RES_EXA)) return fail('reserved');
  if (matchesList(views, SUB, PRE, EXA)) return fail('inappropriate');
  return { ok: true, reason: null, clean, suggestion };
}
